import sys
from rich.console import Console

class ProxyFile:
    def __init__(self, wrapped):
        self.wrapped = wrapped
    def write(self, data):
        self.wrapped.write(data)
    def isatty(self):
        return self.wrapped.isatty()

def test_proxy_isatty():
    # Use sys.stdout as the wrapped file
    proxy = ProxyFile(sys.stdout)
    console = Console(file=proxy)
    print(f"Is terminal: {console.is_terminal}")
    # This should be True if sys.stdout is a TTY

if __name__ == "__main__":
    test_proxy_isatty()
